def pairs_sum_to_zero(l):
    seen = set()
    for x in l:
        if -x in seen:
            return True
        seen.add(x)
    return False

def pairs_sum_to_zero(l):
    values = set(l)
    return any(-x in values and x != -x for x in values)

def sorted_list_sum(lst):
    values = sorted((s for s in lst if len(s) % 2 == 0), reverse=True)
    return sorted(values, key=len)
